<?php
require_once dirname(__DIR__) . '/includes/bootstrap.php';
require_once dirname(__DIR__) . '/includes/layout.php';
$admin=require_admin();$edit=null;$errors=[];
if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM promotions WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
if(is_post()){
    verify_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
    if($action==='delete'){$s=db()->prepare('SELECT banner_image FROM promotions WHERE id=?');$s->execute([$id]);$image=$s->fetchColumn();db()->prepare('DELETE FROM promotions WHERE id=?')->execute([$id]);delete_public_upload($image?:null);log_admin((int)$admin['id'],'Deleted promotion','promotion',$id);flash('success','Promotion deleted.');redirect('admin/promotions.php');}
    $title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$discount=trim((string)($_POST['discount_text']??''));$start=str_replace('T',' ',(string)($_POST['starts_at']??''));$end=str_replace('T',' ',(string)($_POST['ends_at']??''));
    if($title===''||mb_strlen($title)>150)$errors[]='Title is required and must not exceed 150 characters.';
    if(mb_strlen($description)>500)$errors[]='Description must not exceed 500 characters.';
    if(!$start||!$end||strtotime($end)<=strtotime($start))$errors[]='Enter a valid promotion date range.';
    $imagePath=$edit['banner_image']??null;$newImage=null;
    if(!empty($_FILES['banner_image']['name'])){[$ok,$result]=upload_public_image($_FILES['banner_image'],'promotions','promo');if(!$ok)$errors[]=$result;else{$newImage=$result;$imagePath=$result;}}
    elseif(isset($_POST['remove_image']))$imagePath=null;
    if(!$errors){$values=[$title,$description,$discount,$imagePath,(int)($_POST['game_id']??0)?:null,$start,$end,isset($_POST['is_active'])?1:0,(int)($_POST['sort_order']??0)];if($id){$st=db()->prepare('UPDATE promotions SET title=?,description=?,discount_text=?,banner_image=?,game_id=?,starts_at=?,ends_at=?,is_active=?,sort_order=? WHERE id=?');$st->execute([...$values,$id]);if(($edit['banner_image']??null)!==$imagePath)delete_public_upload($edit['banner_image']??null);}else{$st=db()->prepare('INSERT INTO promotions(title,description,discount_text,banner_image,game_id,starts_at,ends_at,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute($values);$id=(int)db()->lastInsertId();}log_admin((int)$admin['id'],'Saved promotion','promotion',$id);flash('success','Promotion saved.');redirect('admin/promotions.php');}elseif($newImage)delete_public_upload($newImage);
}
$games=db()->query('SELECT id,name FROM games ORDER BY name')->fetchAll();$promos=db()->query('SELECT p.*,g.name game_name FROM promotions p LEFT JOIN games g ON g.id=p.game_id ORDER BY p.sort_order,p.starts_at DESC')->fetchAll();render_header('Promotions','admin');$v=fn($k,$d='')=>e($_POST[$k]??($edit[$k]??$d));
?>
<div class="section-head"><div><p class="eyebrow">Marketing</p><h1>Promotions</h1></div></div>
<?php if($errors):?><div class="form-errors"><?php foreach($errors as $error):?><div><?=e($error)?></div><?php endforeach;?></div><?php endif;?>
<div class="admin-editor-layout"><section class="panel"><h2><?=$edit?'Edit promotion':'New promotion'?></h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>">
<div class="form-group"><label>Banner image</label><img class="admin-image-preview promo-preview" data-promo-preview src="<?=e(public_image($edit['banner_image']??null,'default-promo.svg'))?>" alt="Promotion preview"><input type="file" name="banner_image" accept="image/png,image/jpeg,image/webp" data-preview-input="[data-promo-preview]"><small class="help">Recommended ratio: 1600 × 600 px. The slideshow crops other sizes safely.</small><?php if(!empty($edit['banner_image'])):?><label class="checkbox"><input type="checkbox" name="remove_image"><span>Remove current image</span></label><?php endif;?></div>
<div class="form-group"><label>Title</label><input name="title" maxlength="150" value="<?=$v('title')?>" required></div><div class="form-group"><label>Description</label><textarea name="description" maxlength="500"><?=$v('description')?></textarea></div><div class="form-group"><label>Discount text</label><input name="discount_text" maxlength="80" value="<?=$v('discount_text')?>" placeholder="Up to 10% OFF"></div>
<div class="form-group"><label>Specific game (optional)</label><select name="game_id"><option value="">All games</option><?php foreach($games as $game):?><option value="<?=$game['id']?>" <?=((int)($_POST['game_id']??($edit['game_id']??0))===(int)$game['id'])?'selected':''?>><?=e($game['name'])?></option><?php endforeach;?></select></div>
<div class="split"><div class="form-group"><label>Starts</label><input type="datetime-local" name="starts_at" value="<?=e(isset($_POST['starts_at'])?$_POST['starts_at']:($edit?date('Y-m-d\TH:i',strtotime($edit['starts_at'])):date('Y-m-d\TH:i')))?>" required></div><div class="form-group"><label>Ends</label><input type="datetime-local" name="ends_at" value="<?=e(isset($_POST['ends_at'])?$_POST['ends_at']:($edit?date('Y-m-d\TH:i',strtotime($edit['ends_at'])):date('Y-m-d\TH:i',strtotime('+30 days'))))?>" required></div></div>
<div class="form-group"><label>Slide order</label><input type="number" name="sort_order" value="<?=$v('sort_order','0')?>"></div><label class="checkbox"><input type="checkbox" name="is_active" <?=isset($_POST['is_active'])||(!is_post()&&(!$edit||($edit['is_active']??0)))?'checked':''?>><span>Active</span></label><br><button class="button">Save promotion</button></form></section>
<section class="panel"><h2>Promotion list</h2><div class="admin-card-list"><?php foreach($promos as $promo):?><article class="admin-list-card promo-admin-card"><img src="<?=e(public_image($promo['banner_image'],'default-promo.svg'))?>" alt=""><div class="admin-list-content"><span class="badge <?=$promo['is_active']?'success':'danger'?>"><?=$promo['is_active']?'Active':'Inactive'?></span><strong><?=e($promo['title'])?></strong><div class="muted"><?=e($promo['discount_text'])?> · <?=e($promo['game_name']?:'All games')?></div><div class="actions"><a class="button small secondary" href="<?=url('admin/promotions.php?edit='.(int)$promo['id'])?>">Edit</a><form method="post" onsubmit="return confirm('Delete this promotion?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$promo['id']?>"><input type="hidden" name="action" value="delete"><button class="button small danger">Delete</button></form></div></div></article><?php endforeach;?></div></section></div>
<?php render_footer();?>
